
.wrap {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.hero {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.hero__line {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.hero__n {
  font-family: var(--font-mono);
  font-size: 52px;
  font-weight: 400;
  letter-spacing: -0.045em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  color: var(--c-text);
}

.hero__u {
  font-size: 11.5px;
  font-weight: 550;
  color: var(--c-text-faint);
  letter-spacing: 0.06em;
}

.hero__bar {
  height: 3px;
}

.rows {
  display: flex;
  flex-direction: column;
}

.row {
  display: grid;
  grid-template-columns: 72px 1fr;
  gap: 16px;
  align-items: baseline;
  padding: 10px 0;
  border-bottom: 1px solid var(--c-border);

  &:last-child {
    border-bottom: none;
  }
}

.row__k {
  font-size: 11px;
  font-weight: 550;
  color: var(--c-text-faint);
  letter-spacing: 0.05em;
}

.row__v {
  font-size: 13px;
  font-weight: 550;
  color: var(--c-text);
  line-height: 1.55;
}
