
.wrap {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.block__h {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--c-text-faint);
  margin-bottom: 11px;
}

.empty {
  font-size: 12px;
  font-weight: 500;
  color: var(--c-text-faint);
  line-height: 1.65;
}

/* ── 恋爱线 ── */
.lines {
  display: flex;
  flex-direction: column;
}

.line {
  padding: 14px 0;
  border-bottom: 1px solid var(--c-border);

  &:first-child {
    padding-top: 0;
  }

  &:last-child {
    border-bottom: none;
    padding-bottom: 0;
  }
}

.line__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 11px;
}

.line__name {
  font-size: 15.5px;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--c-text);
}

.line__stage {
  font-size: 10px;
  font-weight: 650;
  padding: 2.5px 9px;
  border-radius: 999px;
  background: var(--c-sunken);
  white-space: nowrap;
}

.line__stage--cool {
  color: var(--c-text-muted);
}

.line__stage--warm {
  color: var(--c-warning);
}

.line__stage--hot {
  color: var(--c-primary);
  background: var(--c-primary-dim);
}

.mini {
  display: grid;
  grid-template-columns: 30px 1fr 28px;
  gap: 11px;
  align-items: center;

  & + & {
    margin-top: 7px;
  }
}

.mini__k {
  font-size: 10.5px;
  font-weight: 550;
  color: var(--c-text-faint);
  letter-spacing: 0.04em;
}

.mini__bar {
  height: 3px;
}

.mini__v {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  color: var(--c-text-muted);
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.mini__v--hot {
  color: var(--c-danger);
}

.warn {
  margin-top: 9px;
  font-size: 11px;
  font-weight: 600;
  color: var(--c-danger);
  letter-spacing: 0.01em;
}

/* ── 关系网 ── */
.rel {
  display: flex;
  flex-direction: column;
}

.rel__row {
  display: grid;
  grid-template-columns: 1fr auto 60px 24px;
  gap: 10px;
  align-items: center;
  padding: 9px 0;
  border-bottom: 1px solid var(--c-border);

  &:last-child {
    border-bottom: none;
  }
}

.rel__name {
  font-size: 12.5px;
  font-weight: 550;
  color: var(--c-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tag {
  font-size: 10px;
  font-weight: 650;
  padding: 1.5px 8px;
  border-radius: 999px;
  background: var(--c-sunken);
  white-space: nowrap;
}

.tag--ok {
  color: var(--c-success);
}

.tag--mid {
  color: var(--c-text-muted);
}

.tag--bad {
  color: var(--c-danger);
}

.rel__bar {
  height: 3px;
}

.rel__v {
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 600;
  color: var(--c-text-faint);
  text-align: right;
  font-variant-numeric: tabular-nums;
}
