
.wrap {
  display: flex;
  flex-direction: column;
  gap: 22px;
}

/* ── 状态 ── */
.state {
  display: flex;
  align-items: center;
  gap: 9px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--c-border);
}

.state__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}

.state__dot--ok {
  background: #2fbf4e;
  box-shadow: 0 0 7px rgba(47, 191, 78, 0.6);
}

.state__dot--mid {
  background: #b8b1a4;
}

.state__dot--warn {
  background: #ff9500;
  box-shadow: 0 0 7px rgba(255, 149, 0, 0.6);
}

.state__dot--bad {
  background: #ff3b30;
  box-shadow: 0 0 7px rgba(255, 59, 48, 0.6);
}

.state__label {
  font-size: 14px;
  font-weight: 700;
  letter-spacing: -0.015em;
  color: var(--c-text);
}

.state__sub {
  font-size: 11.5px;
  font-weight: 500;
  color: var(--c-text-muted);
  line-height: 1.45;
}

/* ── 体重 ── */
.weight {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.weight__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.weight__k {
  font-size: 11px;
  font-weight: 550;
  color: var(--c-text-faint);
  letter-spacing: 0.05em;
}

.weight__v {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
}

.weight__num {
  font-family: var(--font-mono);
  font-size: 40px;
  font-weight: 400;
  letter-spacing: -0.04em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  color: var(--c-text);
}

.weight__num--empty {
  color: var(--c-text-faint);
}

.weight__unit {
  font-family: var(--font-mono);
  font-size: 13px;
  font-weight: 550;
  color: var(--c-text-faint);
  letter-spacing: 0.02em;
}

.tri {
  font-size: 12px;
  line-height: 1;
  transform: translateY(-6px);
}

.tri--up {
  color: var(--c-danger);
}

.tri--down {
  color: var(--c-success);
}

.weight__why {
  font-size: 12px;
  font-weight: 500;
  line-height: 1.65;
  color: var(--c-text-muted);
}

.weight__why--empty {
  color: var(--c-text-faint);
}

.weight__daily {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 7px;
  padding-top: 9px;
  border-top: 1px solid var(--c-border);
  font-size: 11px;
  line-height: 1.55;
}

.weight__daily-k {
  color: var(--c-text-faint);
  font-weight: 550;
  letter-spacing: 0.05em;
}

.weight__daily-v {
  font-family: var(--font-mono);
  font-weight: 650;
  font-variant-numeric: tabular-nums;
}

.weight__daily-v--calm {
  color: var(--c-text-muted);
}

.weight__daily-v--warm {
  color: var(--c-warning);
}

.weight__daily-v--hot {
  color: var(--c-danger);
}

.weight__daily-kg {
  color: var(--c-text-faint);
}

.weight__loop {
  color: var(--c-warning);
  font-weight: 600;
}

/* ── 疲劳 ── */
.fatigue {
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding-top: 18px;
  border-top: 1px solid var(--c-border);
}

.fatigue__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.fatigue__k {
  font-size: 11px;
  font-weight: 550;
  color: var(--c-text-faint);
  letter-spacing: 0.05em;
}

.fatigue__v {
  font-family: var(--font-mono);
  font-size: 30px;
  font-weight: 400;
  letter-spacing: -0.03em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  color: var(--c-text);
}

.fatigue__v--hot {
  color: var(--c-danger);
}

.fatigue__hint {
  margin-top: 3px;
  font-size: 11.5px;
  font-weight: 500;
  color: var(--c-text-faint);
  line-height: 1.6;
}

/* ── 伤病 ── */
.block__h {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--c-text-faint);
  margin-bottom: 10px;
}

.prose {
  font-size: 12.5px;
  line-height: 1.8;
  color: var(--c-text-muted);
  white-space: pre-wrap;
  font-weight: 500;
}
