
.wrap {
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.heat {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.heat__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.heat__n {
  font-family: var(--font-mono);
  font-size: 42px;
  font-weight: 400;
  letter-spacing: -0.04em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.heat__n--hot {
  color: var(--c-danger);
}

.heat__bar {
  height: 3px;
}

.tag {
  font-size: 10.5px;
  font-weight: 650;
  padding: 3px 10px;
  border-radius: 999px;
  background: var(--c-sunken);
  letter-spacing: 0.03em;
  white-space: nowrap;
}

.tag--ok {
  color: var(--c-success);
}

.tag--mid {
  color: var(--c-text-muted);
}

.tag--warn {
  color: var(--c-warning);
}

.tag--bad {
  color: var(--c-danger);
}

.crisis {
  display: flex;
  align-items: baseline;
  gap: 9px;
  margin-top: 4px;
  padding: 9px 12px;
  border-radius: var(--radius-sm);
  background: rgba(224, 52, 43, 0.07);
}

.crisis__k {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: var(--c-danger);
  flex-shrink: 0;
}

.crisis__v {
  font-size: 12px;
  font-weight: 550;
  color: var(--c-danger);
  line-height: 1.55;
}

.block__h {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--c-text-faint);
  margin-bottom: 11px;
}

.issues {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.issue {
  font-size: 12.5px;
  font-weight: 500;
  color: var(--c-text);
  padding-left: 13px;
  position: relative;
  line-height: 1.65;

  &::before {
    content: '';
    position: absolute;
    left: 0;
    top: 0.66em;
    width: 3.5px;
    height: 3.5px;
    border-radius: 50%;
    background: var(--c-text-faint);
  }
}

.fan-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 8px;
}

.fan-size {
  font-size: 13px;
  font-weight: 600;
  color: var(--c-text);
}

.fan-power {
  font-family: var(--font-mono);
  font-size: 14px;
  font-weight: 600;
  color: var(--c-text);
  font-variant-numeric: tabular-nums;
}

.comp {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 13px 22px;
  margin-top: 17px;
}

.comp__meta {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 5px;
}

.comp__k {
  font-size: 11px;
  font-weight: 550;
  color: var(--c-text-faint);
}

.comp__v {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  color: var(--c-text-muted);
  font-variant-numeric: tabular-nums;
}

.comp__bar {
  height: 3px;
}
