
.wrap {
  display: flex;
  flex-direction: column;
  gap: 22px;
}

/* ── 身份：无框表格 ── */
.grid2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0 26px;
}

.field {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 0;
  border-bottom: 1px solid var(--c-border);
}

.field__k {
  font-size: 11px;
  font-weight: 550;
  color: var(--c-text-faint);
  letter-spacing: 0.05em;
  flex-shrink: 0;
}

.field__v {
  font-size: 13px;
  font-weight: 600;
  color: var(--c-text);
  text-align: right;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.field__v--num {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.015em;
}

/* ── 区块标题 ── */
.block__h {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--c-text-faint);
  margin-bottom: 11px;
}

/* ── 资源层级 ── */
.tier {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding-bottom: 15px;
  margin-bottom: 15px;
  border-bottom: 1px solid var(--c-border);
}

.tier__v {
  font-size: 26px;
  font-weight: 700;
  letter-spacing: -0.035em;
  line-height: 1.1;
  color: var(--c-text);
}

.tier__sub {
  font-size: 11.5px;
  font-weight: 500;
  color: var(--c-text-muted);
  line-height: 1.55;
}

.meter {
  display: flex;
  flex-direction: column;
  gap: 6px;

  & + & {
    margin-top: 14px;
  }
}

.meter__row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.meter__k {
  font-size: 11.5px;
  font-weight: 550;
  color: var(--c-text-muted);
}

.meter__v {
  font-family: var(--font-mono);
  font-size: 12.5px;
  font-weight: 600;
  color: var(--c-text);
  font-variant-numeric: tabular-nums;
}

.prose {
  font-size: 12.5px;
  line-height: 1.8;
  color: var(--c-text-muted);
  white-space: pre-wrap;
  letter-spacing: 0.005em;
  font-weight: 500;
}
