
.wrap {
  display: flex;
  flex-direction: column;
  gap: 22px;
}

/* ── 积蓄 ── */
.net {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--c-border);
}

.net__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.net__k {
  font-size: 11px;
  font-weight: 550;
  color: var(--c-text-faint);
  letter-spacing: 0.05em;
}

.net__v {
  font-family: var(--font-mono);
  font-size: 34px;
  font-weight: 400;
  letter-spacing: -0.04em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.net__v--ok {
  color: var(--c-text);
}

.net__v--warn {
  color: var(--c-warning);
}

.net__v--bad {
  color: var(--c-danger);
}

.net__cny {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  color: var(--c-text-faint);
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.net__hint {
  margin-top: 5px;
  font-size: 12px;
  font-weight: 500;
  color: var(--c-text-muted);
  line-height: 1.65;
}

/* ── 收支 ── */
.flows {
  display: flex;
  flex-direction: column;
}

.flow {
  padding: 13px 0;
  border-bottom: 1px solid var(--c-border);

  &:first-child {
    padding-top: 0;
  }

  &:last-child {
    border-bottom: none;
    padding-bottom: 0;
  }
}

.flow__row {
  display: flex;
  align-items: baseline;
  gap: 9px;
}

.flow__k {
  font-size: 11.5px;
  font-weight: 550;
  color: var(--c-text-muted);
  flex-shrink: 0;
}

.flow__v {
  font-family: var(--font-mono);
  font-size: 17px;
  font-weight: 500;
  letter-spacing: -0.015em;
  margin-left: auto;
  font-variant-numeric: tabular-nums;
  color: var(--c-text);
}

.flow__cycle {
  font-size: 10.5px;
  font-weight: 550;
  color: var(--c-text-faint);
  flex-shrink: 0;
  width: 22px;
  text-align: left;
}

.flow__sub {
  display: flex;
  align-items: baseline;
  gap: 11px;
  margin-top: 5px;
}

.flow__cny {
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 500;
  color: var(--c-text-faint);
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}

.flow__note {
  font-size: 11.5px;
  font-weight: 500;
  color: var(--c-text-faint);
  line-height: 1.55;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.block__h {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--c-text-faint);
  margin-bottom: 10px;
}

.prose {
  font-size: 12.5px;
  line-height: 1.8;
  color: var(--c-text-muted);
  white-space: pre-wrap;
  font-weight: 500;
}

.guard {
  font-size: 11.5px;
  font-weight: 500;
  color: var(--c-text-faint);
  line-height: 1.65;
  border-top: 1px solid var(--c-border);
  padding-top: 14px;
}
